import pytest

from bedrock_protocol import v975, v1001, v2168

# generated by gophertunnel de090ae:
# packet.ResourcePackClientResponse{Response: packet.PackResponseSendPacks, PacksToDownload: []string{"pack_a",
# "pack_b"}}
V1001_DOWNLOADING = bytes.fromhex("020200067061636b5f61067061636b5f62")

# generated by gophertunnel de090ae:
# packet.ResourcePackClientResponse{Response: packet.PackResponseCompleted}
V1001_STACK_FINISHED = bytes.fromhex("040000")

# generated by gophertunnel b8bd735:
# packet.ResourcePackClientResponse{Response: packet.PackResponseSendPacks, PacksToDownload: []string{"pack_a",
# "pack_b"}}
V2168_DOWNLOADING = bytes.fromhex("010b646f776e6c6f6164696e6702067061636b5f61067061636b5f62")

# generated by gophertunnel b8bd735:
# packet.ResourcePackClientResponse{Response: packet.PackResponseCompleted}
V2168_STACK_FINISHED = bytes.fromhex("03197265736f757263657061636b737461636b66696e6973686564")

# generated by gophertunnel b8bd735:
# packet.ResourcePackClientResponse{Response: packet.PackResponseRefused}
V2168_CANCEL = bytes.fromhex("000663616e63656c")

GOLDENS = [
    pytest.param(
        v975.ResourcePackClientResponsePacket(
            response=v975.ResourcePackResponse.DOWNLOADING, downloading_packs=["pack_a", "pack_b"]
        ),
        V1001_DOWNLOADING,
        id="v975-downloading",
    ),
    pytest.param(
        v1001.ResourcePackClientResponsePacket(
            response=v1001.ResourcePackResponse.DOWNLOADING, downloading_packs=["pack_a", "pack_b"]
        ),
        V1001_DOWNLOADING,
        id="v1001-downloading",
    ),
    pytest.param(
        v1001.ResourcePackClientResponsePacket(response=v1001.ResourcePackResponse.RESOURCE_PACK_STACK_FINISHED),
        V1001_STACK_FINISHED,
        id="v1001-stack-finished",
    ),
    pytest.param(
        v2168.ResourcePackClientResponsePacket(
            response=v2168.ResourcePackClientResponsePacket.Downloading(downloading_packs=["pack_a", "pack_b"])
        ),
        V2168_DOWNLOADING,
        id="v2168-downloading",
    ),
    pytest.param(
        v2168.ResourcePackClientResponsePacket(
            response=v2168.ResourcePackClientResponsePacket.ResourcePackStackFinished()
        ),
        V2168_STACK_FINISHED,
        id="v2168-stack-finished",
    ),
    pytest.param(
        v2168.ResourcePackClientResponsePacket(response=v2168.ResourcePackClientResponsePacket.Cancel()),
        V2168_CANCEL,
        id="v2168-cancel",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_resource_pack_client_response_is_packet_8(version):
    assert version.PACKETS[8] is version.ResourcePackClientResponsePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_client_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_client_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("version", "wire"),
    [
        pytest.param(v1001, V2168_CANCEL, id="v1001-reads-v2168-cancel"),
        pytest.param(v1001, V2168_DOWNLOADING, id="v1001-reads-v2168-downloading"),
        pytest.param(v2168, V1001_STACK_FINISHED, id="v2168-reads-v1001-stack-finished"),
        pytest.param(v2168, V1001_DOWNLOADING, id="v2168-reads-v1001-downloading"),
    ],
)
def test_decode_rejects_the_other_era_body(version, wire):
    with pytest.raises(ValueError, match="at byte"):
        version.ResourcePackClientResponsePacket.from_bytes(wire)
